class OrderProcessingEverything {
    double x; // mutowalne, mylaca nazwa

    double process(int n, int q, double p, String c, String cpn) {
        // n=liczba pozycji, q=ilosc, p=cena, c=kraj, cpn=kod kuponu - WALIDACJA + LICZENIE + LOG naraz
        double t = q * p;
        if (c.equals("PL")) t = t * 1.23;
        else if (c.equals("DE")) t = t * 1.19;
        else if (c.equals("US")) t = t * 1.0;
        if (cpn.length() > 0) t = t * 0.9; // NullPointerException jesli cpn == null
        x = t;
        System.out.println("Processed: " + t);
        return x;
    }
}

record Order(int quantity, double unitPrice, String country, Optional<String> couponCode) {
    Order { // fail-fast walidacja w konstruktorze kompaktowym
        if (quantity <= 0) throw new IllegalArgumentException("quantity musi byc > 0");
    }
}

interface TaxCalculator { double taxRateFor(String country); }

class StandardTaxCalculator implements TaxCalculator {
    public double taxRateFor(String country) {
        return switch (country) {
            case "PL" -> 1.23;
            case "DE" -> 1.19;
            default -> 1.0;
        };
    }
}

class OrderProcessor {
    private final TaxCalculator taxCalculator;
    OrderProcessor(TaxCalculator taxCalculator) { this.taxCalculator = taxCalculator; }

    double calculateTotalWithTax(Order order) {
        double base = order.quantity() * order.unitPrice();
        return applyCouponIfPresent(base * taxCalculator.taxRateFor(order.country()), order);
    }

    private double applyCouponIfPresent(double amount, Order order) {
        return order.couponCode().isPresent() ? amount * 0.9 : amount;
    }
}
